const D = { energy: .6, scale: 1, speed: 1, density: .55, relief: .6, hue: 34, x: .5, y: .5, style: 'stone', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// ACANTHUS -- the classical running scroll (rinceau). Stacked bands of alternating
// volutes uncurl across the frame, each wrapped in a cluster of deeply-cut acanthus
// leaves. The relief is modelled entirely by a raking light that slowly wheels
// around, so every lobe's lit and shadowed faces trade places -- carved stone that
// never sits still. Offered as limestone chiaroscuro, gilded carving, terracotta /
// bronze, or a line engraving.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sd = (P.seed | 0);
const fr = i => { let h = (Math.imul((i ^ sd) | 0, 374761393) + 0x9e3779b9) | 0; h = Math.imul(h ^ (h >>> 15), 668265263); h ^= h >>> 13; return ((h >>> 0) % 100000) / 100000; };

// ---- layout: bands of volutes, each with a leaf fan ------------------------
const nBands = 2 + Math.round(P.density * 3);            // 2..5 bands
const perBand = 4 + Math.round(P.density * 5);           // volutes per band
const key = width + 'x' + height + '|' + P.seed + '|' + nBands + '|' + perBand;
if (S.key !== key) {
  S.key = key; S.bands = [];
  for (let b = 0; b < nBands; b++) {
    const vols = [];
    const dir0 = fr(b * 5 + 1) > 0.5 ? 1 : -1;
    for (let v = 0; v < perBand; v++) {
      const dir = dir0 * (v % 2 ? -1 : 1);               // alternate up/down curl
      const nl = 4 + Math.round(fr(b * 13 + v * 7) * 3);
      const leaves = [];
      for (let l = 0; l < nl; l++) leaves.push({ a0: -0.6 + (l / nl) * 2.2 + fr(l + v * 3 + b) * 0.15, len: 0.7 + fr(l * 7 + v) * 0.6, curl: (fr(l * 11 + v) - 0.5) * 1.2, ph: fr(l * 3 + v + b) * 6.28 });
      vols.push({ dir, turns: 1.1 + fr(v * 9 + b) * 0.7, leaves, jt: (fr(v + b * 4) - 0.5), sz: 0.85 + fr(v * 5 + b) * 0.4 });
    }
    S.bands.push(vols);
  }
}

// ---- palette / render mode --------------------------------------------------
const st = P.style;
let bg, baseH, baseS, baseB, warm, lineMode = false, addMode = false;
if (st === 'gilt') { bg = [(P.hue + 210) % 360, 60, 12]; baseH = P.hue; baseS = 62; baseB = 60; warm = 8; }
else if (st === 'terracotta') { bg = [16, 55, 16]; baseH = 15; baseS = 66; baseB = 58; warm = 6; }
else if (st === 'engraving') { bg = [36, 12, 66]; baseH = 32; baseS = 16; baseB = 30; warm = 0; lineMode = true; }
else { bg = [34, 14, 30]; baseH = 34; baseS = 12; baseB = 66; warm = 5; }   // stone (default)

// ---- background: toned ground with a soft light gradient --------------------
push(); noStroke(); rectMode(CORNER);
fill(bg[0], bg[1], bg[2]); rect(0, 0, width, height);
const lgx = 0.5 + 0.4 * Math.cos(K.t * 0.13);
for (let g = 8; g >= 0; g--) {
  fill(bg[0], Math.max(0, bg[1] - 4), bg[2] + (8 - g) * (lineMode ? 2.4 : 3.2), lineMode ? 7 : 10);
  ellipse(lgx * width, height * 0.5, u * (0.4 + g * 0.22), u * (0.4 + g * 0.22));
}
pop();

// ---- animation drivers ------------------------------------------------------
const sp = 0.3 + P.speed * 0.9;
const relief = 0.4 + P.relief * 0.9;
const eGlow = 0.6 + P.energy * 0.9 + A.rms * 0.2;
// raking light wheels on two incommensurate rates -> lit faces trade, never re-phases
const lightAng = K.t * 0.19 * sp + 0.5 * Math.sin(K.t * 0.071 * sp);
const lx = Math.cos(lightAng), ly = Math.sin(lightAng);
// a slow drawing/uncurl phase so tips breathe outward
const grow = t2 => 0.86 + 0.14 * Math.sin(K.t * 0.8 * sp + t2);

function shade(nx, ny) {                                   // -1..1 dot with light
  const nl = Math.hypot(nx, ny) || 1;
  return (nx / nl) * lx + (ny / nl) * ly;
}

// ---- draw an acanthus leaf lobe (curled spike) ------------------------------
function lobe(ox, oy, ang, len, curl, ph, R2) {
  const tx = Math.cos(ang), ty = Math.sin(ang);
  const px = Math.cos(ang + 1.57), py = Math.sin(ang + 1.57);
  const g = grow(ph);
  const L = len * R2 * g;
  const w = L * 0.34;
  // curled tip
  const tipx = ox + tx * L + px * curl * L * 0.5;
  const tipy = oy + ty * L + py * curl * L * 0.5;
  const s = shade(tx + px * curl * 0.5, ty + py * curl * 0.5);     // lobe face normal ~ leaf direction
  const litB = Math.min(100, (baseB * (0.42 + 0.58 * (s * 0.5 + 0.5)) + warm) * eGlow);
  const shdB = baseB * (0.18 + 0.2 * (s * 0.5 + 0.5));
  if (lineMode) {
    // engraving: hatch the lobe, denser on shadow side
    stroke(baseH, baseS, 22, 60); strokeWeight(Math.max(0.5, R2 * 0.006));
    noFill();
    beginShape(); vertex(ox + px * w, oy + py * w); bezierVertex(ox + tx * L * 0.5 + px * w, oy + ty * L * 0.5 + py * w, tipx + px * w * 0.3, tipy + py * w * 0.3, tipx, tipy); bezierVertex(ox + tx * L * 0.5 - px * w, oy + ty * L * 0.5 - py * w, ox - px * w, oy - py * w, ox - px * w, oy - py * w); endShape(CLOSE);
    const nh = Math.round(3 + (1 - (s * 0.5 + 0.5)) * 5);
    for (let h = 1; h < nh; h++) { const f = h / nh; stroke(baseH, baseS, 30, 40); line(ox + tx * L * f * 0.9 - px * w * (1 - f), oy + ty * L * f * 0.9 - py * w * (1 - f), ox + tx * L * f * 0.9 + px * w * (1 - f), oy + ty * L * f * 0.9 + py * w * (1 - f)); }
    return;
  }
  // shadow underside
  noStroke();
  fill(baseH, baseS + 6, shdB);
  beginShape(); vertex(ox + px * w, oy + py * w); bezierVertex(ox + tx * L * 0.45 + px * w * 1.1, oy + ty * L * 0.45 + py * w * 1.1, tipx + px * w * 0.4, tipy + py * w * 0.4, tipx, tipy); bezierVertex(ox + tx * L * 0.45 - px * w * 1.1, oy + ty * L * 0.45 - py * w * 1.1, ox - px * w, oy - py * w, ox + px * w, oy + py * w); endShape(CLOSE);
  // lit body (offset toward light)
  fill(baseH, Math.max(0, baseS - 14 * (litB / 100)), litB);
  beginShape(); vertex(ox + px * w * 0.6 + lx * relief * w * 0.3, oy + py * w * 0.6 + ly * relief * w * 0.3); bezierVertex(ox + tx * L * 0.5 + px * w * 0.6, oy + ty * L * 0.5 + py * w * 0.6, tipx, tipy, tipx, tipy); bezierVertex(ox + tx * L * 0.5 - px * w * 0.3, oy + ty * L * 0.5 - py * w * 0.3, ox - px * w * 0.2, oy - py * w * 0.2, ox + px * w * 0.6 + lx * relief * w * 0.3, oy + py * w * 0.6 + ly * relief * w * 0.3); endShape(CLOSE);
  // bright spine highlight along the leaf
  if (s > -0.1) { stroke(baseH, Math.max(0, baseS - 30), Math.min(100, litB + 24), 60 + 30 * (s * 0.5 + 0.5)); strokeWeight(Math.max(0.6, R2 * 0.008)); noFill(); line(ox, oy, tipx, tipy); }
  noStroke();
}

// ---- draw one volute (spiral eye + leaf fan) --------------------------------
function volute(cx, cy, dir, vol, R2) {
  // spiral eye
  const eyeR = R2 * 0.5 * vol.sz;
  const turns = vol.turns;
  const NS = 30;
  noFill();
  for (let i = 1; i <= NS; i++) {
    const s0 = (i - 1) / NS, s1 = i / NS;
    const a0 = s0 * turns * 6.283 * dir, a1 = s1 * turns * 6.283 * dir;
    const r0 = eyeR * (0.12 + s0 * 0.9), r1 = eyeR * (0.12 + s1 * 0.9);
    const x0 = cx + Math.cos(a0) * r0, y0 = cy + Math.sin(a0) * r0;
    const x1 = cx + Math.cos(a1) * r1, y1 = cy + Math.sin(a1) * r1;
    const nx = Math.cos((a0 + a1) * 0.5), ny = Math.sin((a0 + a1) * 0.5);
    const s = shade(nx, ny);
    if (lineMode) { stroke(baseH, baseS, 26, 70); strokeWeight(Math.max(0.5, R2 * 0.012 * (1 - s0 * 0.6))); }
    else { const b = Math.min(100, (baseB * (0.4 + 0.6 * (s * 0.5 + 0.5)) + warm) * eGlow); stroke(baseH, Math.max(0, baseS - 10 * (b / 100)), b, 90); strokeWeight(Math.max(0.8, R2 * 0.05 * (1 - s0 * 0.55))); }
    line(x0, y0, x1, y1);
  }
  // leaf fan wrapping the volute
  for (const lf of vol.leaves) lobe(cx, cy, lf.a0 * dir - 1.2 * dir, lf.len, lf.curl * dir, lf.ph, R2 * vol.sz);
}

// ---- compose bands ----------------------------------------------------------
push();
if (addMode) blendMode(BLEND);
const R2 = u * 0.16 * P.scale;
for (let b = 0; b < nBands; b++) {
  const vols = S.bands[b];
  const by = height * ((b + 0.5) / nBands);
  const amp = u * 0.05 * P.scale;
  for (let v = 0; v < vols.length; v++) {
    const vx = width * ((v + 0.5) / vols.length);
    const vy = by + Math.sin(v * 1.3 + b) * amp + vols[v].jt * amp;
    volute(vx, vy, vols[v].dir, vols[v], R2);
  }
}
pop();

blendMode(BLEND);
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(bg[0], bg[1], bg[2], 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
drawingContext.shadowBlur = 0;
